<?php if ($uid !== (int)($_SESSION['user_id'] ?? 0)): ?><form class="d-inline" method="post" action="index.php?controller=usuarios&action=cambiarEstado" onsubmit="return confirm('¿Confirmas cambiar el estado de esta cuenta?')"><input type="hidden" name="ID_Usuario" value="<?= $uid ?>"><input type="hidden" name="Estado" value="<?= (int)$u['Estado']===1?0:1 ?>"><button class="btn btn-sm btn-<?= (int)$u['Estado']===1?'outline-danger':'outline-success' ?>"><i class="bi bi-<?= (int)$u['Estado']===1?'person-slash':'person-check' ?>"></i> <?= (int)$u['Estado']===1?'Desactivar':'Activar' ?></button></form><?php endif; ?></td></tr>
