<div class="modal fade" id="modalEditarUsuario" tabindex="-1" aria-labelledby="tituloEditarUsuario" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" method="post" action="index.php?controller=usuarios&action=editar"><div class="modal-header"><h5 class="modal-title" id="tituloEditarUsuario">Actualizar usuario</h5><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Cerrar"></button></div><div class="modal-body">
<input type="hidden" name="ID_Usuario" id="editarUsuarioId"><div class="mb-3"><label class="form-label" for="editarNombre">Nombre completo</label><input class="form-control" id="editarNombre" name="Nombre" maxlength="50" required></div><div class="mb-3"><label class="form-label" for="editarUsuario">Nombre de usuario</label><input class="form-control" id="editarUsuario" name="Usuario" maxlength="50" required></div><div class="mb-3"><label class="form-label" for="editarPassword">Nueva contraseña (opcional)</label><input class="form-control" id="editarPassword" type="password" name="Password" minlength="8" autocomplete="new-password" placeholder="Dejar vacío para conservarla"><div class="form-text">Si la cambias, debe tener al menos 8 caracteres.</div></div><div class="mb-3"><label class="form-label" for="editarRol">Rol</label><select class="form-select" id="editarRol" name="Rol" required><option value="usuario">Usuario</option><option value="admin">Administrador</option></select></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button type="submit" class="btn btn-primary"><i class="bi bi-save"></i> Guardar cambios</button></div></form></div></div>
<div class="modal fade" id="modalCrearUsuario" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" method="post" action="index.php?controller=usuarios&action=crear"><div class="modal-header"><h5 class="modal-title"><i class="bi bi-person-plus"></i> Registrar usuario</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="mb-3"><label class="form-label">Nombre completo</label><input class="form-control" name="Nombre" maxlength="50" required></div><div class="mb-3"><label class="form-label">Nombre de usuario</label><input class="form-control" name="Usuario" maxlength="50" required autocomplete="username"></div><div class="mb-3"><label class="form-label">Contraseña</label><input class="form-control" type="password" name="Password" minlength="8" required autocomplete="new-password"><div class="form-text">Mínimo 8 caracteres.</div></div><div class="mb-3"><label class="form-label">Rol</label><select class="form-select" name="Rol" required><option value="usuario" selected>Usuario</option><option value="admin">Administrador</option></select></div></div><div class="modal-footer"><button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary"><i class="bi bi-save"></i> Registrar</button></div></form></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.btn-editar-usuario').forEach(function(btn){btn.addEventListener('click',function(){document.getElementById('editarUsuarioId').value=this.dataset.id;document.getElementById('editarNombre').value=this.dataset.nombre;document.getElementById('editarUsuario').value=this.dataset.usuario;document.getElementById('editarRol').value=this.dataset.rol;document.getElementById('editarPassword').value='';});});});</script>
